def run(scene, robot):
    tub = scene.containers()[0]
    items = scene.with_role("moved")
    if not items:
        items = scene.of_kind("pen")
    for obj in items:
        cur = scene.get(obj.name)
        dst = scene.get(tub.name)
        if scene.is_inside(cur, dst):
            continue
        robot.pick(cur)
        robot.place_in(scene.get(tub.name))

def run(scene, robot):
    tub = scene.get("white tub")
    candidates = {}
    for o in scene.with_role("moved"):
        candidates[o.name] = o
    for o in scene.of_kind("pen"):
        candidates[o.name] = o
    for name in list(candidates.keys()):
        obj = scene.get(name)
        if scene.is_inside(obj, scene.get(tub.name)):
            continue
        robot.pick(obj)
        robot.place_in(scene.get(tub.name))
